"""build — orchestrate the structural graph: discover files, resolve the cross-file edges that the
per-file index could not (IMPORTS/CALLS need the global symbol table), persist the store, and answer the
named 2-hop queries WITHOUT an LLM.

`index_file` (Fase 1) is purely LOCAL by design (so it is incremental-safe). The edges that span files
are resolved HERE, deterministically, from the attrs the fragments carry: a File's `imports` (dotted names)
and a Symbol's `calls` (bare names). Resolution is cheap (no AST re-parse) so it re-runs on every rebuild.
"""
from __future__ import annotations

import json
from collections import defaultdict
from pathlib import Path

from .model import Edge, EdgeKind, FileFragment, Graph, NodeKind
from .python_index import index_file

DEFAULT_ROOTS = ("src/metafactory", "seed")
STORE_DIR = ".graph"


# ── discovery ────────────────────────────────────────────────────────────────
def discover_python(repo_root: Path, roots=DEFAULT_ROOTS) -> list[str]:
    """Every .py under the given roots, as sorted POSIX relpaths (deterministic, no __pycache__)."""
    repo_root = Path(repo_root)
    found: list[str] = []
    for root in roots:
        base = repo_root / root
        if not base.exists():
            continue
        for p in base.rglob("*.py"):
            if "__pycache__" in p.parts:
                continue
            found.append(p.relative_to(repo_root).as_posix())
    return sorted(found)


# ── cross-file edge resolution ─────────────────────────────────────────────────
def _module_map(file_ids: list[str], source_root: str = "src") -> dict[str, str]:
    """dotted module name -> File node id, for files under `source_root` (the dir on PYTHONPATH).
    `src/metafactory/a/b.py` -> `metafactory.a.b`; `.../a/__init__.py` -> `metafactory.a`."""
    prefix = source_root.rstrip("/") + "/"
    out: dict[str, str] = {}
    for fid in file_ids:
        rel = fid.split(":", 1)[1]
        if not rel.startswith(prefix) or not rel.endswith(".py"):
            continue
        mod = rel[len(prefix):-len(".py")]
        if mod.endswith("/__init__"):
            mod = mod[: -len("/__init__")]
        out[mod.replace("/", ".")] = fid
    return out


def _resolve_module(dotted: str, mod2file: dict[str, str]) -> str | None:
    """Map a dotted import to a File id by trying decreasing prefixes, so `from a.b import c`
    (dotted `a.b.c`) resolves to the module `a.b` when `c` is a symbol, not a submodule."""
    parts = dotted.split(".")
    for cut in range(len(parts), 0, -1):
        cand = ".".join(parts[:cut])
        if cand in mod2file:
            return mod2file[cand]
    return None


def resolve_cross_file_edges(graph: Graph, source_root: str = "src") -> None:
    """Add File--IMPORTS-->File and Symbol--CALLS-->Symbol edges, derived from fragment attrs."""
    file_ids = [n.id for n in graph.nodes_of(NodeKind.FILE)]
    mod2file = _module_map(file_ids, source_root)
    for fn in graph.nodes_of(NodeKind.FILE):
        for dotted in fn.attrs.get("imports", []):
            tgt = _resolve_module(dotted, mod2file)
            if tgt and tgt != fn.id:
                graph.add_edge(Edge(fn.id, tgt, EdgeKind.IMPORTS))

    name2syms: dict[str, list[str]] = defaultdict(list)
    for sn in graph.nodes_of(NodeKind.SYMBOL):
        short = sn.name.rsplit(".", 1)[-1]
        name2syms[short].append(sn.id)
    for sn in graph.nodes_of(NodeKind.SYMBOL):
        for called in sn.attrs.get("calls", []):
            for tgt in name2syms.get(called, []):
                if tgt != sn.id:
                    graph.add_edge(Edge(sn.id, tgt, EdgeKind.CALLS))


# ── full structural build ───────────────────────────────────────────────────────
def build_code_graph(repo_root: Path, roots=DEFAULT_ROOTS) -> tuple[Graph, dict[str, FileFragment]]:
    """Index every file (full, non-incremental) and resolve cross-file edges. Returns the graph and the
    fragment map (the store the incremental rebuild diffs against)."""
    repo_root = Path(repo_root)
    fragments: dict[str, FileFragment] = {}
    for rel in discover_python(repo_root, roots):
        fragments[rel] = index_file(repo_root, rel)
    graph = graph_from_fragments(fragments)
    return graph, fragments


def graph_from_fragments(fragments: dict[str, FileFragment]) -> Graph:
    graph = Graph()
    for frag in fragments.values():
        graph.add_fragment(frag)
    resolve_cross_file_edges(graph)
    return graph


# ── store (re-derivable cache; gitignored) ──────────────────────────────────────
def store_path(repo_root: Path) -> Path:
    return Path(repo_root) / STORE_DIR / "fragments.json"


def save_store(repo_root: Path, fragments: dict[str, FileFragment]) -> Path:
    path = store_path(repo_root)
    path.parent.mkdir(parents=True, exist_ok=True)
    blob = {rel: frag.to_dict() for rel, frag in sorted(fragments.items())}
    path.write_text(json.dumps(blob, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return path


def load_store(repo_root: Path) -> dict[str, FileFragment]:
    path = store_path(repo_root)
    if not path.exists():
        return {}
    blob = json.loads(path.read_text(encoding="utf-8"))
    return {rel: FileFragment.from_dict(d) for rel, d in blob.items()}


def save_graph(repo_root: Path, graph: Graph) -> Path:
    path = Path(repo_root) / STORE_DIR / "graph.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(graph.to_json(), encoding="utf-8")
    return path


# ── named no-LLM queries (the spine IS the navigation) ──────────────────────────
def governing_adrs(graph: Graph, symbol_id: str) -> list[str]:
    """2-hop, no LLM: symbol --DEFINED_IN--> file <--GOVERNS-- ADR. "Which ADR governs this symbol?\""""
    return graph.reachable(symbol_id, [(EdgeKind.DEFINED_IN, True), (EdgeKind.GOVERNS, False)])


def requirements_satisfied_by(graph: Graph, station_id: str) -> list[str]:
    """1-hop: station --SATISFIES--> requirement."""
    return graph.reachable(station_id, [(EdgeKind.SATISFIES, True)])


def requirements_for_proof(graph: Graph, proof_id: str) -> list[str]:
    """2-hop, no LLM: proof --VERIFIES--> station --SATISFIES--> requirement."""
    return graph.reachable(proof_id, [(EdgeKind.VERIFIES, True), (EdgeKind.SATISFIES, True)])

"""doc_graph — ADR-026 Fase F1 (DOC-GRAPH-LIVENESS): fold the doc corpus into the project graph as Doc
nodes + `CITES` (Doc -> Doc) / `EVIDENCES` (Doc -> File/Artifact) edges, so "is this doc still
referenced?" is a graph query, not a literal grep (a literal grep produced a FALSE orphan for
`PLAN-EXECUTE-RUNBOOK.md`, cited bare — no `.md`, no backticks — from `cli.py:1104`).

Scope boundary (read before touching `evidence_liveness`): the MANDATORY tooth gates ONLY CITES-shaped
tokens (`.md` paths and bare `ADR-NNN`) found in LIVING (non-exempt) docs. `EVIDENCES` targets (arbitrary
code/proof paths a doc mentions) are recorded when they happen to exist, but their ABSENCE is NEVER
gated — many are legitimately ephemeral/gitignored (`.proof/`, `.gen/`, build output); gating them would
manufacture false reds unrelated to doc rot.

Robust ID matching (`ingest_doc_edges`): a doc may be cited by its full path, path-minus-`.md`, bare
basename, or (for ADRs) `ADR-NNN` — resolution tries each in a deterministic order, falling back to
filesystem existence and a repo-wide basename search before giving up.
"""
from __future__ import annotations

import os
import posixpath
import re
import subprocess
from pathlib import Path, PurePosixPath

from .. import docs_manifest
from .model import Edge, EdgeKind, Graph, Node, NodeKind

_SKIP_DIRS = {".git", "__pycache__", "node_modules", "dist", ".proof", ".gen", ".graph", ".pytest_cache"}
_ASF_DIRNAME = "Agent_Systems_Factory"

# Same one-liner `ingest.py` uses for ADR filenames — duplicated locally (that name is private there).
_ADR_FILE_RE = re.compile(r"^(\d{1,4})-")

_MD_LINK_RE = re.compile(r"\]\(([^)\s#]+\.md)(?:#[^)]*)?\)")
_MD_BACKTICK_RE = re.compile(r"`([^`\s]+\.md)`")
_ADR_CITE_RE = re.compile(r"(?<!ASF/)\bADR-0*(\d{1,4})\b")

_CERRADO_RE = re.compile(r"(?:Estado|Status):\s*\*\*(?:CERRADO|CLOSED)\*\*")
_ABIERTO_RE = re.compile(r"(?:Estado|Status):\s*\*\*(?:ABIERTO|OPEN)\*\*")

_BAD_CHARS = "*<>~…"
_BAD_DOTDOT_RE = re.compile(r"\.\.(?!/)")


# ── Doc node ingestion ───────────────────────────────────────────────────────
def ingest_docs(graph: Graph, repo_root: Path) -> int:
    """One Doc node per doc in `docs_manifest.doc_homes()` x `doc_set()` (reuse, single source — do not
    re-glob). attrs: relpath (POSIX, repo-relative), last_edit (`git log -1 --format=%cI -- <path>`,
    cwd=repo_root; "" if the command fails or is empty — never raise), exempt (bool, see `is_exempt`).
    Returns the count of Doc nodes added."""
    repo_root = Path(repo_root)
    n = 0
    for home in docs_manifest.doc_homes(repo_root):
        is_meta = home == repo_root
        for d in docs_manifest.doc_set(home, meta_extras=is_meta):
            rel = d.relative_to(repo_root).as_posix()
            text = d.read_text(encoding="utf-8")
            body = docs_manifest.split_seal(text)[1]
            attrs = {
                "relpath": rel,
                "last_edit": _last_edit(repo_root, rel),
                "exempt": is_exempt(rel, body),
            }
            graph.add_node(Node.make(NodeKind.DOC, rel, rel, attrs))
            n += 1
    return n


def _last_edit(repo_root: Path, rel: str) -> str:
    try:
        out = subprocess.run(
            ["git", "log", "-1", "--format=%cI", "--", rel],
            cwd=repo_root, capture_output=True, text=True,
        )
    except OSError:
        return ""
    if out.returncode != 0:
        return ""
    return out.stdout.strip()


def is_exempt(relpath: str, body: str) -> bool:
    """A doc is exempt from `evidence_liveness` (LIVING docs must resolve; these three classes don't):
    (a) `"decisions"` is a path part (immutable ADRs), (b) basename == "LOG.md" (append-only), (c) a
    `"work"` path part AND `body` matches the dual-accept closed grammar (English-forward
    `Status: **CLOSED**` OR legacy Spanish `Estado: **CERRADO**`, ADR-026 — closed increment, frozen)."""
    p = PurePosixPath(relpath)
    if "decisions" in p.parts:
        return True
    if p.name == "LOG.md":
        return True
    if "work" in p.parts and _CERRADO_RE.search(body):
        return True
    return False


# ── extraction ────────────────────────────────────────────────────────────────
def _dropped(tok: str) -> bool:
    if any(c in tok for c in _BAD_CHARS):
        return True
    if _BAD_DOTDOT_RE.search(tok):
        return True
    return False


def extract_refs(body: str) -> list[tuple[str, str]]:
    """Pure regex extraction, no filesystem access. Returns (kind, token) pairs, kind in {"md", "adr"}:
    - "md": every markdown-link target ending `.md` AND every backtick-wrapped token ending `.md`.
    - "adr": every bare `ADR-NNN` NOT preceded by `ASF/` (`ASF/ADR-NNN` cites the sibling
      Agent_Systems_Factory repo's OWN decisions — out of scope, never extracted at all).
    A token (either kind) is DROPPED (never yielded) if it contains any of `*`, `<`, `>`, `~`, the
    unicode ellipsis `…`, OR a mid-token `..` not immediately followed by `/` (glob/placeholder prose
    like `docs/*.md`, `work/<incremento>.md`, `S0..S15-INCREMENT.md`; a genuine `../` parent-relative
    path like `../INDEX.md` must still be YIELDED — only bare mid-token `..` ranges are placeholder noise)."""
    refs: list[tuple[str, str]] = []
    for m in _MD_LINK_RE.finditer(body):
        tok = m.group(1)
        if not _dropped(tok):
            refs.append(("md", tok))
    for m in _MD_BACKTICK_RE.finditer(body):
        tok = m.group(1)
        if not _dropped(tok):
            refs.append(("md", tok))
    for m in _ADR_CITE_RE.finditer(body):
        tok = m.group(1)
        if not _dropped(tok):
            refs.append(("adr", tok))
    return refs


# ── ADR decisions table ────────────────────────────────────────────────────────
def _decisions_table(repo_root: Path) -> dict[int, str]:
    """{adr_num: relpath} from `docs/decisions/*.md` filenames matching `^(\\d{1,4})-` (same regex
    `ingest.py` uses for ADR ingestion — duplicated locally, `_ADR_FILE_RE`)."""
    repo_root = Path(repo_root)
    decisions_dir = repo_root / "docs" / "decisions"
    table: dict[int, str] = {}
    if not decisions_dir.is_dir():
        return table
    for md in sorted(decisions_dir.glob("*.md")):
        m = _ADR_FILE_RE.match(md.name)
        if not m:
            continue
        table[int(m.group(1))] = md.relative_to(repo_root).as_posix()
    return table


# ── edge resolution ───────────────────────────────────────────────────────────
def _lookup_table(doc_nodes: list[Node]) -> dict[str, str]:
    """{relpath, relpath-minus-.md, basename, basename-minus-.md} -> doc node id, first (sorted-id) wins."""
    table: dict[str, str] = {}
    for n in doc_nodes:
        rel = n.attrs["relpath"]
        base = PurePosixPath(rel).name
        for key in (rel, _strip_md(rel), base, _strip_md(base)):
            table.setdefault(key, n.id)
    return table


def _strip_md(s: str) -> str:
    return s[:-3] if s.endswith(".md") else s


def _rel_str(path: Path, repo_root: Path) -> str:
    """A stable, repo-relative-ish POSIX label for a resolved filesystem path (works for the ASF
    sibling too, via `os.path.relpath`, e.g. `../Agent_Systems_Factory/.claude/agents/x.md`)."""
    try:
        return path.resolve().relative_to(repo_root.resolve()).as_posix()
    except ValueError:
        return Path(os.path.relpath(path.resolve(), repo_root.resolve())).as_posix()


def _fs_hit(path: Path, repo_root: Path, graph: Graph) -> tuple[str, bool]:
    rel = _rel_str(path, repo_root)
    doc_id = f"{NodeKind.DOC.value}:{rel}"
    if graph.node(doc_id) is not None:
        return doc_id, True
    return rel, False


def _resolve_md(tok: str, citing_dir: PurePosixPath, lookup: dict[str, str],
                 repo_root: Path, asf_root: Path, graph: Graph) -> tuple[str, bool] | None:
    joined = posixpath.normpath(posixpath.join(str(citing_dir), tok))
    for candidate in (joined, tok, PurePosixPath(tok).name):
        hit = lookup.get(candidate)
        if hit:
            return hit, True

    fs_candidates = [repo_root / citing_dir / tok, repo_root / tok, asf_root / tok]
    for c in fs_candidates:
        if c.is_file():
            return _fs_hit(c, repo_root, graph)

    basename = PurePosixPath(tok).name
    for root in (repo_root, asf_root):
        if not root.is_dir():
            continue
        matches = sorted(
            p for p in root.rglob(basename)
            if not (set(p.relative_to(root).parts) & _SKIP_DIRS)
        )
        if matches:
            return _fs_hit(matches[0], repo_root, graph)
    return None


def ingest_doc_edges(graph: Graph, repo_root: Path) -> tuple[int, int, list[tuple[str, str]]]:
    """For every Doc node (sorted by id, deterministic), read its body (`docs_manifest.split_seal`), run
    `extract_refs`, and resolve each token — see the module docstring for the resolution order. Returns
    `(n_cites, n_evidences, unresolved)`. `unresolved` is the SOLE input `evidence_liveness` reads — the
    gate must NOT re-implement extraction/resolution, it must call this function and filter by
    `graph.node(f"{NodeKind.DOC.value}:{rel}").attrs["exempt"]`."""
    repo_root = Path(repo_root)
    asf_root = repo_root.parent / _ASF_DIRNAME
    decisions = _decisions_table(repo_root)
    doc_nodes = sorted(graph.nodes_of(NodeKind.DOC), key=lambda n: n.id)
    lookup = _lookup_table(doc_nodes)

    n_cites = 0
    n_evidences = 0
    unresolved: list[tuple[str, str]] = []

    for doc in doc_nodes:
        rel = doc.attrs["relpath"]
        path = repo_root / rel
        if not path.is_file():
            continue
        text = path.read_text(encoding="utf-8")
        body = docs_manifest.split_seal(text)[1]
        citing_dir = PurePosixPath(rel).parent

        for kind, tok in extract_refs(body):
            if kind == "md":
                hit = _resolve_md(tok, citing_dir, lookup, repo_root, asf_root, graph)
                if hit is None:
                    unresolved.append((rel, tok))
                    continue
                hit_id, is_doc = hit
                if is_doc:
                    graph.add_edge(Edge(doc.id, hit_id, EdgeKind.CITES))
                    n_cites += 1
                else:
                    file_id = f"{NodeKind.FILE.value}:{hit_id}"
                    if graph.node(file_id) is not None:
                        art_id = file_id
                    else:
                        art_node = Node.make(NodeKind.ARTIFACT, hit_id, hit_id, {"exists": True})
                        graph.add_node(art_node)
                        art_id = art_node.id
                    graph.add_edge(Edge(doc.id, art_id, EdgeKind.EVIDENCES))
                    n_evidences += 1
            else:  # "adr"
                num = int(tok)
                dec_rel = decisions.get(num)
                dec_doc_id = f"{NodeKind.DOC.value}:{dec_rel}" if dec_rel else None
                if dec_doc_id and graph.node(dec_doc_id) is not None:
                    graph.add_edge(Edge(doc.id, dec_doc_id, EdgeKind.CITES))
                    n_cites += 1
                else:
                    unresolved.append((rel, f"ADR-{tok}"))
    return n_cites, n_evidences, unresolved


# ── liveness (reachability) ────────────────────────────────────────────────────
def live_roots(graph: Graph, repo_root: Path) -> set[str]:
    """Doc node ids considered inherently live: `docs/STATE.md` of every `doc_homes()` home + `CLAUDE.md`
    of every home that has one + any Doc whose body matches the dual-accept open grammar (English-forward
    `Status: **OPEN**` OR legacy Spanish `Estado: **ABIERTO**`, ADR-026 — an open increment)."""
    repo_root = Path(repo_root)
    roots: set[str] = set()
    for home in docs_manifest.doc_homes(repo_root):
        state = home / "docs" / "STATE.md"
        if state.is_file():
            roots.add(f"{NodeKind.DOC.value}:{state.relative_to(repo_root).as_posix()}")
        claude = home / "CLAUDE.md"
        if claude.is_file():
            roots.add(f"{NodeKind.DOC.value}:{claude.relative_to(repo_root).as_posix()}")
    for doc in graph.nodes_of(NodeKind.DOC):
        rel = doc.attrs.get("relpath", "")
        path = repo_root / rel
        if not path.is_file():
            continue
        body = docs_manifest.split_seal(path.read_text(encoding="utf-8"))[1]
        if _ABIERTO_RE.search(body):
            roots.add(doc.id)
    return roots


def reachable_docs(graph: Graph, repo_root: Path) -> set[str]:
    """Forward BFS over CITES edges (Doc -> Doc only) from `live_roots()`, returns the closure INCLUDING
    the roots themselves. Bounded fixed-point loop (a few hundred nodes, no external library needed)."""
    seen = set(live_roots(graph, repo_root))
    frontier = list(seen)
    while frontier:
        nxt: list[str] = []
        for nid in frontier:
            for e in graph.out_edges(nid, EdgeKind.CITES):
                if e.dst not in seen:
                    seen.add(e.dst)
                    nxt.append(e.dst)
        frontier = nxt
    return seen


def orphan_docs(graph: Graph, repo_root: Path) -> list[dict]:
    """Every Doc node whose id is NOT in `reachable_docs()`, as `{"relpath": ..., "last_edit": ...}`,
    sorted by `last_edit` ascending (oldest first; unknown/empty dates sort LAST)."""
    reachable = reachable_docs(graph, repo_root)
    orphans = [
        {"relpath": d.attrs.get("relpath", ""), "last_edit": d.attrs.get("last_edit", "")}
        for d in graph.nodes_of(NodeKind.DOC) if d.id not in reachable
    ]
    orphans.sort(key=lambda o: (o["last_edit"] == "", o["last_edit"]))
    return orphans

"""model — the content-addressed graph: Node/Edge/Graph + FileFragment + traversal + JSON serde.

A node's id IS its content address: a deterministic string derived from its identity (kind + canonical
key), so re-deriving the same code/spec yields byte-identical ids (the property that lets the store be
diffed and the rebuild be incremental). A node ALSO carries `content_hash` — a hash of its semantic
payload — so a changed node is detectable without re-reading the whole graph (the Merkle leaf, Fase 3).

Edges are directed and typed (EdgeKind). `Graph` keeps forward + reverse adjacency so a traversal can
step along an edge in either direction (the 2-hop query mixes one forward + one reverse hop, e.g.
symbol --DEFINED_IN--> file <--GOVERNS-- ADR = "which ADR governs this symbol", no LLM).
"""
from __future__ import annotations

import hashlib
import json
from collections import defaultdict
from dataclasses import dataclass, field
from enum import Enum


class NodeKind(str, Enum):
    FILE = "File"
    SYMBOL = "Symbol"
    REQUIREMENT = "Requirement"
    CAPABILITY = "Capability"
    STATION = "Station"
    PROOF = "Proof"
    ARTIFACT = "Artifact"
    DECISION = "Decision"   # an ADR
    DOC = "Doc"              # a docs/**.md (or CLAUDE.md) node (ADR-026 F1, DOC-GRAPH-LIVENESS)


class EdgeKind(str, Enum):
    DEFINED_IN = "DEFINED_IN"   # Symbol -> File
    IMPORTS = "IMPORTS"         # File -> File
    CALLS = "CALLS"             # Symbol -> Symbol
    IMPLEMENTS = "IMPLEMENTS"   # Capability -> Requirement ; Artifact -> Capability
    VERIFIES = "VERIFIES"       # Station -> Capability ; Proof -> Station
    SATISFIES = "SATISFIES"     # Station -> Requirement
    GOVERNS = "GOVERNS"         # Decision(ADR) -> File
    SUPERSEDES = "SUPERSEDES"   # Decision -> Decision (reserved; ingested when declared)
    GENERATES = "GENERATES"     # Station -> Artifact (reserved; the generate slot)
    CITES = "CITES"             # Doc -> Doc (a doc references another doc; robust ID matching)
    EVIDENCES = "EVIDENCES"     # Doc -> File/Artifact (a doc references a concrete non-doc artifact; best-effort)


def content_hash(payload: object) -> str:
    """A stable 16-hex content hash of any JSON-able payload (canonical, sorted keys)."""
    blob = json.dumps(payload, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(blob.encode("utf-8")).hexdigest()[:16]


@dataclass(frozen=True)
class Node:
    id: str
    kind: NodeKind
    name: str
    attrs: dict = field(default_factory=dict)
    content_hash: str = ""

    @staticmethod
    def make(kind: NodeKind, key: str, name: str, attrs: dict | None = None) -> "Node":
        """Build a node whose id is content-addressed (`kind:key`) and whose content_hash covers
        its semantic payload (name + attrs). Same identity + same payload => byte-identical node."""
        attrs = dict(attrs or {})
        nid = f"{kind.value}:{key}"
        ch = content_hash({"id": nid, "name": name, "attrs": attrs})
        return Node(id=nid, kind=kind, name=name, attrs=attrs, content_hash=ch)

    def to_dict(self) -> dict:
        return {"id": self.id, "kind": self.kind.value, "name": self.name,
                "attrs": self.attrs, "content_hash": self.content_hash}

    @staticmethod
    def from_dict(d: dict) -> "Node":
        return Node(id=d["id"], kind=NodeKind(d["kind"]), name=d["name"],
                    attrs=dict(d.get("attrs") or {}), content_hash=d.get("content_hash", ""))


@dataclass(frozen=True)
class Edge:
    src: str
    dst: str
    kind: EdgeKind

    def to_dict(self) -> dict:
        return {"src": self.src, "dst": self.dst, "kind": self.kind.value}

    @staticmethod
    def from_dict(d: dict) -> "Edge":
        return Edge(src=d["src"], dst=d["dst"], kind=EdgeKind(d["kind"]))


@dataclass
class FileFragment:
    """The structural subgraph derived from ONE source file: the unit of incrementality (Fase 3).
    `content_hash` is the file's leaf hash; if it is unchanged the fragment is reused, not re-parsed."""
    relpath: str
    content_hash: str
    nodes: list[Node] = field(default_factory=list)
    edges: list[Edge] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {"relpath": self.relpath, "content_hash": self.content_hash,
                "nodes": [n.to_dict() for n in self.nodes],
                "edges": [e.to_dict() for e in self.edges]}

    @staticmethod
    def from_dict(d: dict) -> "FileFragment":
        return FileFragment(relpath=d["relpath"], content_hash=d["content_hash"],
                            nodes=[Node.from_dict(n) for n in d.get("nodes", [])],
                            edges=[Edge.from_dict(e) for e in d.get("edges", [])])


class Graph:
    """A content-addressed multigraph. Nodes are keyed by id (last write wins on identical id, which
    is fine: identical id => identical content by construction). Edges are de-duplicated on (src,dst,kind)."""

    def __init__(self) -> None:
        self._nodes: dict[str, Node] = {}
        self._edges: set[tuple[str, str, str]] = set()
        self._out: dict[str, list[Edge]] = defaultdict(list)
        self._in: dict[str, list[Edge]] = defaultdict(list)

    # ── mutation ────────────────────────────────────────────────────────────
    def add_node(self, node: Node) -> None:
        self._nodes[node.id] = node

    def add_edge(self, edge: Edge) -> None:
        key = (edge.src, edge.dst, edge.kind.value)
        if key in self._edges:
            return
        self._edges.add(key)
        self._out[edge.src].append(edge)
        self._in[edge.dst].append(edge)

    def add_fragment(self, frag: FileFragment) -> None:
        for n in frag.nodes:
            self.add_node(n)
        for e in frag.edges:
            self.add_edge(e)

    # ── access ──────────────────────────────────────────────────────────────
    def node(self, nid: str) -> Node | None:
        return self._nodes.get(nid)

    @property
    def nodes(self) -> list[Node]:
        return list(self._nodes.values())

    @property
    def edges(self) -> list[Edge]:
        return [Edge(s, d, EdgeKind(k)) for (s, d, k) in sorted(self._edges)]

    def nodes_of(self, kind: NodeKind) -> list[Node]:
        return [n for n in self._nodes.values() if n.kind == kind]

    def out_edges(self, nid: str, kind: EdgeKind | None = None) -> list[Edge]:
        return [e for e in self._out.get(nid, []) if kind is None or e.kind == kind]

    def in_edges(self, nid: str, kind: EdgeKind | None = None) -> list[Edge]:
        return [e for e in self._in.get(nid, []) if kind is None or e.kind == kind]

    # ── traversal ─────────────────────────────────────────────────────────────
    def step(self, nid: str, kind: EdgeKind, *, forward: bool) -> list[str]:
        """One hop along `kind`. forward => follow src->dst from nid; reverse => dst->src into nid."""
        if forward:
            return [e.dst for e in self.out_edges(nid, kind)]
        return [e.src for e in self.in_edges(nid, kind)]

    def reachable(self, start: str, steps: list[tuple[EdgeKind, bool]]) -> list[str]:
        """Follow an ordered list of (edge_kind, forward?) hops from `start`; return the node ids
        reached after the LAST hop (deduped, sorted). This IS the no-LLM multi-hop query primitive."""
        frontier = [start]
        for kind, forward in steps:
            nxt: list[str] = []
            for nid in frontier:
                nxt.extend(self.step(nid, kind, forward=forward))
            frontier = nxt
        return sorted(set(frontier))

    # ── serde ─────────────────────────────────────────────────────────────────
    def to_dict(self) -> dict:
        return {"nodes": [n.to_dict() for n in sorted(self._nodes.values(), key=lambda n: n.id)],
                "edges": [e.to_dict() for e in self.edges]}

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), indent=2, ensure_ascii=False) + "\n"

    @staticmethod
    def from_dict(d: dict) -> "Graph":
        g = Graph()
        for nd in d.get("nodes", []):
            g.add_node(Node.from_dict(nd))
        for ed in d.get("edges", []):
            g.add_edge(Edge.from_dict(ed))
        return g

    @staticmethod
    def from_json(text: str) -> "Graph":
        return Graph.from_dict(json.loads(text))

"""quality — Fase 4: deterministic SWE quality metrics over the graph (size + coupling), the substrate
of a `meta check` gate. NOT an LLM judge (I-3): every number is re-derived from the AST graph.

Thresholds are DATA (the plan's dial, ADR-012-style): file LOC, functions per file, longest function,
and import cycles. The defaults are calibrated so the live substrate passes with margin while the known
8.5k-line monolith fails decisively — the two-sided tooth the gate check exercises. Existing files near
the line (e.g. `cli.py`) are deferred debt (the monolith split is Fase 3 MONOLITH-REFACTOR), so the
file-LOC limit sits well above them; the gate's job here is to STOP a NEW monolith (the 2026-06-25 rule).
"""
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from .model import EdgeKind, Graph, NodeKind


@dataclass(frozen=True)
class Thresholds:
    max_file_loc: int = 2000
    max_funcs_per_file: int = 80
    max_func_loc: int = 200

    @staticmethod
    def from_dict(d: dict | None) -> "Thresholds":
        d = d or {}
        base = Thresholds()
        return Thresholds(
            max_file_loc=int(d.get("max_file_loc", base.max_file_loc)),
            max_funcs_per_file=int(d.get("max_funcs_per_file", base.max_funcs_per_file)),
            max_func_loc=int(d.get("max_func_loc", base.max_func_loc)),
        )


@dataclass(frozen=True)
class Violation:
    relpath: str
    metric: str
    value: int | str
    limit: int | str

    def __str__(self) -> str:
        return f"{self.relpath}: {self.metric}={self.value} > limit {self.limit}"


def _relpath(file_id: str) -> str:
    return file_id.split(":", 1)[1] if ":" in file_id else file_id


def file_violations(graph: Graph, th: Thresholds) -> list[Violation]:
    """Per-File size/coupling violations: file LOC, #functions, longest function."""
    out: list[Violation] = []
    for fn in sorted(graph.nodes_of(NodeKind.FILE), key=lambda n: n.id):
        rel = _relpath(fn.id)
        loc = int(fn.attrs.get("loc", 0))
        if loc > th.max_file_loc:
            out.append(Violation(rel, "file_loc", loc, th.max_file_loc))
        syms = [graph.node(e.src) for e in graph.in_edges(fn.id, EdgeKind.DEFINED_IN)]
        funcs = [s for s in syms if s and s.attrs.get("symtype") == "function"]
        if len(funcs) > th.max_funcs_per_file:
            out.append(Violation(rel, "funcs", len(funcs), th.max_funcs_per_file))
        longest = max((int(s.attrs.get("loc", 0)) for s in funcs), default=0)
        if longest > th.max_func_loc:
            out.append(Violation(rel, "func_loc", longest, th.max_func_loc))
    return out


def import_cycles(graph: Graph) -> list[list[str]]:
    """Strongly-connected components of size > 1 over File--IMPORTS-->File (i.e. import cycles).
    Tarjan, iterative, deterministic (nodes visited in sorted order)."""
    adj: dict[str, list[str]] = {}
    for fn in graph.nodes_of(NodeKind.FILE):
        adj[fn.id] = sorted(e.dst for e in graph.out_edges(fn.id, EdgeKind.IMPORTS))
    index: dict[str, int] = {}
    low: dict[str, int] = {}
    on_stack: set[str] = set()
    stack: list[str] = []
    counter = [0]
    sccs: list[list[str]] = []

    def strongconnect(start: str) -> None:
        work = [(start, 0)]
        while work:
            v, i = work[-1]
            if i == 0:
                index[v] = low[v] = counter[0]
                counter[0] += 1
                stack.append(v)
                on_stack.add(v)
            recursed = False
            for j in range(i, len(adj.get(v, []))):
                w = adj[v][j]
                if w not in index:
                    work[-1] = (v, j + 1)
                    work.append((w, 0))
                    recursed = True
                    break
                if w in on_stack:
                    low[v] = min(low[v], index[w])
            if recursed:
                continue
            if low[v] == index[v]:
                comp: list[str] = []
                while True:
                    w = stack.pop()
                    on_stack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                if len(comp) > 1:
                    sccs.append(sorted(_relpath(x) for x in comp))
            work.pop()
            if work:
                p, _ = work[-1]
                low[p] = min(low[p], low[v])

    for v in sorted(adj):
        if v not in index:
            strongconnect(v)
    return sorted(sccs)


@dataclass
class Report:
    violations: list[Violation]
    cycles: list[list[str]]

    @property
    def clean(self) -> bool:
        return not self.violations and not self.cycles

    def summary(self) -> str:
        if self.clean:
            return "clean"
        parts = []
        if self.violations:
            parts.append(f"{len(self.violations)} size/coupling violation(s)")
        if self.cycles:
            parts.append(f"{len(self.cycles)} import cycle(s)")
        return "; ".join(parts)


def evaluate_graph(graph: Graph, th: Thresholds, *, check_cycles: bool = True) -> Report:
    return Report(file_violations(graph, th), import_cycles(graph) if check_cycles else [])


def evaluate_file(repo_root: Path, relpath: str, th: Thresholds) -> list[Violation]:
    """Size violations for ONE file (no cross-file edges) — the two-sided-tooth probe: a monolith must
    come back RED, a healthy module GREEN, regardless of whether it lives in the indexed substrate."""
    from .python_index import index_file
    g = Graph()
    g.add_fragment(index_file(repo_root, relpath))
    return file_violations(g, th)


def discover_authored_codegen(repo_root: Path) -> list[str]:
    """Every AUTHORED factory-codegen .py (sorted POSIX relpaths), DATA-agnostic — a glob, no factory or
    tech is named (anti-overfit; the `generality` gate sanctions this). Excludes derived/vendored trees:
    `build/` (generated products) and `__pycache__`. The forward 'no monolith anywhere' frontier: a NEW
    factory scaffolder that grows into a monolith must turn `meta check` RED (the 2026-06-25 rule)."""
    repo_root = Path(repo_root)
    base = repo_root / "factories"
    if not base.exists():
        return []
    out: list[str] = []
    for p in sorted(base.glob("*/codegen/**/*.py")):
        if "__pycache__" in p.parts or "build" in p.parts:
            continue
        out.append(p.relative_to(repo_root).as_posix())
    return sorted(out)

